def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    # Thin, connected linework is the divider color; solid blocks are not.
    candidates = [c for c in counts if c != bg]
    def line_score(color):
        thin = 0
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    degree = sum(0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color
                                 for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)))
                    if degree <= 2:
                        thin += 1
        return thin / counts[color]
    wall = max(candidates, key=lambda c: line_score(c))

    # Find regions separated by divider cells and identify each region's
    # non-background signal color.
    comp = [[-1] * w for _ in range(h)]
    labels = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == wall or comp[r][c] >= 0:
                continue
            idx = len(labels)
            q = deque([(r, c)])
            comp[r][c] = idx
            members = []
            while q:
                y, x = q.popleft()
                members.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= yy < h and 0 <= xx < w and comp[yy][xx] < 0
                            and grid[yy][xx] != wall):
                        comp[yy][xx] = idx
                        q.append((yy, xx))
            freq = Counter(grid[y][x] for y, x in members if grid[y][x] != bg)
            labels.append(freq.most_common(1)[0][0] if freq else None)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall:
                continue
            near = []
            for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if 0 <= rr < h and 0 <= cc < w and comp[rr][cc] >= 0:
                    label = labels[comp[rr][cc]]
                    if label is not None:
                        near.append(label)
            if near:
                out[r][c] = Counter(near).most_common(1)[0][0]
    return out
