    bg = freq.most_common(1)[0][0]

    # Divider strokes are frequent, but relatively thin compared with the
    # large solid color fields and sample patches.
    scores = {}
    for color, n in freq.items():
        if color == bg:
            continue
        same = 0
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    same += sum(
                        0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color
                        for rr, cc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1))
                    )
        avg = same / n
        scores[color] = n * (4 - avg)
    wall = max(scores, key=scores.get)

    # Open regions are separated by the divider. Their embedded colored
    # marks identify which color should be used on bordering divider cells.
    region = [[-1] * w for _ in range(h)]
    labels = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == wall or region[r][c] != -1:
                continue
            idx = len(labels)
            q = deque([(r, c)])
            region[r][c] = idx
            colors = Counter()
            while q:
                y, x = q.popleft()
                if grid[y][x] != bg:
                    colors[grid[y][x]] += 1
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if (0 <= yy < h and 0 <= xx < w and region[yy][xx] == -1
                            and grid[yy][xx] != wall):
                        region[yy][xx] = idx
                        q.append((yy, xx))
            labels.append(colors.most_common(1)[0][0] if colors else None)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall:
                continue
            adjacent = []
            for rr, cc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if 0 <= rr < h and 0 <= cc < w:
                    idx = region[rr][cc]
                    if idx >= 0 and labels[idx] is not None:
                        adjacent.append(labels[idx])
            if adjacent:
                counts = Counter(adjacent)
                if len(counts) == 1 or counts.most_common()[0][1] > counts.most_common()[1][1]:
                    out[r][c] = counts.most_common(1)[0][0]
    return out
