                    q = deque([(r, c)])
                    seen[r][c] = True
                    cells = []
                    while q:
                        y, x = q.popleft()
                        cells.append((y, x))
                        for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                            if (0 <= yy < h and 0 <= xx < w and not seen[yy][xx]
                                    and grid[yy][xx] == color):
                                seen[yy][xx] = True
                                q.append((yy, xx))
                    if len(cells) > len(best):
                        best = cells
            return best

        panels = [(6, largest_component(6)), (8, largest_component(8))]
        out = [row[:] for row in grid]
        for r in range(h):
            for c in range(w):
                if grid[r][c] == 1:
                    distances = [
                        min(abs(r-y) + abs(c-x) for y, x in cells)
                        for _, cells in panels
                    ]
                    out[r][c] = panels[0 if distances[0] < distances[1] else 1][0]
        return out

    # General maze/panel transformation used by the demonstrations.
